from .image_feedback import image_feedback_call,step_image_feedback,feedback_definition

class AdmissionError(TransitionError):pass
class ThinkingLadderExhausted(AdmissionError):pass

@dataclass(frozen=True)
class Value:
    type: str
    data: object
    @property
    def wire(self):return (self.type,self.data)

@dataclass(frozen=True)
class Step:
    status: str
    frame: str
    value: dict|None=None

_TYPES={'Text':str,'ToolProposal':str,'ModelInput':(str,list),'COWSource':dict,'World':str,
        'ModelOutput':dict,'ToolPlan':dict,'ToolOutcome':dict,'Verification':dict,'RepeatResult':dict}
_INITIAL={'Text','ToolProposal','ModelInput','COWSource'}
_SUPPORTED={'TEXT','VALUE','EXPAND','PLAN','ACT','TRANSFORM','VERIFY','REPEAT'}
_TRANSFORMS={'cow-source':('ModelOutput','COWSource'),'tool-feedback':('ToolOutcome','Text')}

def _value(wire):
    if type(wire) is not tuple or len(wire)!=2:raise AdmissionError('typed value required')
    name,data=wire
    allowed=_TYPES.get(name)
    if allowed is None or type(data) not in (allowed if type(allowed) is tuple else (allowed,)):raise AdmissionError('value has a different registered type')
    encode(wire)
    if name=='ModelInput':
        try:data=model_content(data)
        except ValueError as exc:raise AdmissionError('invalid typed model input: '+str(exc)) from exc
    if name=='COWSource':
        if set(data)!={'head','mode'} or data['mode'] not in ('ask','append_user'):raise AdmissionError('explicit context-only ask or stopped append_user boundary required')
        BranchHead.parse(data['head'])
    return Value(name,data)

def _output(statement):return statement.output or statement.label

def _reference(log,wire):return log.read_artifact(Artifact(*wire))

def _returned(kernel,frame):
    return decode(_reference(kernel.log,frame['result']))[2]

class Interpreter:
    def __init__(self,kernel,registry,*,adapter=None,profiles=None,verification=None):
        if not isinstance(registry,ToolRegistry):raise AdmissionError('actual host ToolRegistry required')
        self.kernel=kernel;self.registry=registry;self.adapter=adapter
        try:
            policy=FileReadbackPolicy
            if type(verification) is dict:
                if 'commands' in verification:policy=CommandEvidencePolicy
                elif 'interactive_captures' in verification:policy=InteractivePagePolicy
                elif 'inspected_captures' in verification:policy=InspectedPagePolicy
                elif 'captures' in verification:policy=PageCapturePolicy
            self._file_policy=None if verification is None else policy.admit(verification,registry)
        except (ValueError,ToolRejected) as exc:raise AdmissionError('invalid host file verification policy: '+str(exc)) from exc
        self._profile_data=encode({} if profiles is None else profiles)
        if type(self.profiles) is not dict or any(type(k) is not str or type(v) is not dict for k,v in self.profiles.items()):raise AdmissionError('host model profiles must be named mappings')
        for profile in self.profiles.values():
            if profile.get('kind')=='image-feedback':
                if (set(profile)!={'kind','source'} or type(profile['source']) is not str
                    or not re.fullmatch(r'[A-Za-z][A-Za-z0-9_.-]*',profile['source'])):
                    raise AdmissionError('image feedback profile requires one named source binding')
            elif set(profile)-{'settings','grammar_state','output_format','request_tokens','max_requests','max_output_tokens','max_result_bytes','thinking_ladder'}:
                raise AdmissionError('unknown model profile field')
        for profile in self.profiles.values():
            if 'thinking_ladder' not in profile:continue
            try:rungs=ladder_module.ladder(profile['thinking_ladder'])
            except ValueError as exc:raise AdmissionError('unknown thinking ladder mode') from exc
            if profile.get('output_format')!='thinking' or profile.get('grammar_state')!=rungs[0].grammar_state:
                raise AdmissionError('thinking ladder requires its initial immutable budget grammar')
        from . import kernel as kernel_module, language as language_module, records as records_module, tool_dispatch as tool_module, verification as verification_module
        sources=tuple(sha256(Path(module).read_bytes()).hexdigest() for module in [__file__,kernel_module.__file__,language_module.__file__,records_module.__file__,tool_module.__file__,verification_module.__file__,inputs_module.__file__,image_feedback_module.__file__,ladder_module.__file__,retry_module.__file__])
        self.identity=sha256(encode(('bw.interpreter.v1',registry.identity,None if adapter is None else adapter.identity,
            self.profiles,None if self._file_policy is None else self._file_policy.identity,sources))).hexdigest()

    @property
    def profiles(self):
        # Caller mutations cannot silently change the frozen execution identity.
        return decode(self._profile_data)

    def _check_program(self,source,bindings):
        return self.preflight(source,{name:value.type for name,value in bindings.items()})

    def preflight(self,source,binding_types):
        # Lexical types are compile-time inputs, not invented native snapshots.
        if type(binding_types) is not dict or any(t not in _TYPES for t in binding_types.values()):raise AdmissionError('registered lexical types required')
        program=parse(source)
        if len(program)!=1 or program[0].opcode!='FLOW' or program[0].output is not None or program[0].attributes:
            raise AdmissionError('one root FLOW with no parameters required')
        env=dict(binding_types)
        def require(name,types):
            if env.get(name) not in types:raise AdmissionError('missing or incompatible typed binding: '+name)
        def check(body):
            for statement in body:
                op=statement.opcode;a=dict(statement.attributes)
                if op not in _SUPPORTED:raise AdmissionError('unsupported execution operation: '+op)
                if op=='TEXT':typ='Text'
                elif op=='VALUE':
                    require(a['ref'],{a['type']});typ=a['type']
                elif op=='EXPAND':
                    require(a['from'],{'COWSource'});require(a['task'],{'Text','ModelInput'})
                    if self.adapter is None or a['profile'] not in self.profiles or 'kind' in self.profiles[a['profile']]:raise AdmissionError('registered model profile required')
                    typ='ModelOutput'
                elif op=='PLAN':
                    require(a['from'],{'ModelOutput','ToolProposal'});require(a['against'],{'World'});typ='ToolPlan'
                elif op=='ACT':require(a['plan'],{'ToolPlan'});typ='ToolOutcome'
                elif op=='TRANSFORM':
                    if a['contract'] not in _TRANSFORMS:raise AdmissionError('unsupported transform contract')
                    source_type,typ=_TRANSFORMS[a['contract']];require(a['input'],{source_type})
                    if 'profile' in a:
                        selected=self.profiles.get(a['profile'],{})
                        if a['contract']!='tool-feedback' or self.adapter is None or selected.get('kind')!='image-feedback':
                            raise AdmissionError('registered image feedback profile required')
                        require(selected['source'],{'COWSource'});typ='ModelInput'
                elif op=='VERIFY':
                    contracts={'command-evidence-and-finish':CommandEvidencePolicy,'file-readback-and-finish':FileReadbackPolicy,
                        'page-capture-and-finish':PageCapturePolicy,'page-inspection-and-finish':InspectedPagePolicy,
                        'interactive-page-inspection-and-finish':InteractivePagePolicy}
                    if a['contract'] not in ('unit-tests-and-finish',*contracts) or 'profile' in a:raise AdmissionError('unsupported verifier contract')
                    if a['contract'] in contracts:
                        if self._file_policy is None:raise AdmissionError('host file verification policy required')
                        if type(self._file_policy) is not contracts[a['contract']]:
                            raise AdmissionError('matching host capture policy required')
                    elif not self.registry._grant.allow_tests or any(p=='tests' or p.startswith('tests/') for p in (*self.registry._grant.edit_paths,*self.registry._grant.create_paths)):
                        raise AdmissionError('verification requires granted tests with protected test paths')
                    require(a['input'],{'ToolOutcome'});typ='Verification'
                elif op=='REPEAT':
                    if a['exhausted'] not in ('stop','abandon'):raise AdmissionError('unsupported exhausted disposition')
                    check(statement.body);require(a['until'],{'Verification'});typ='RepeatResult'
                env[_output(statement)]=typ
        check(program[0].body)
        return program[0]

    def start(self,source,bindings=None):
        supplied={} if bindings is None else bindings
        if type(supplied) is not dict:raise AdmissionError('named host bindings required')
        frozen={}
        for name,value in supplied.items():
            if type(name) is not str or not re.fullmatch(r'[A-Za-z][A-Za-z0-9_.-]*',name) or name=='world' or not isinstance(value,Value) or value.type not in _INITIAL:
                raise AdmissionError('invalid initial host binding')
            frozen[name]=_value(decode(encode(value.wire)))
        frozen['world']=Value('World',self.registry.world)
        root=self._check_program(source,frozen);canonical=render((root,))
        inputs=encode(dict(schema=1,identity=self.identity,bindings={k:v.wire for k,v in frozen.items()}))
        frames=self.kernel.frames()
        if frames:
            old=self.kernel.frame('program')
            if _reference(self.kernel.log,old['definition'])!=canonical.encode() or _reference(self.kernel.log,old['inputs'])!=inputs:raise AdmissionError('run already owns a different program or inputs')
            return old
        return self.kernel.create_root('program','program-attempt',self.kernel.log.put_artifact(canonical.encode()),self.kernel.log.put_artifact(inputs),ResultContract('ProgramResult','record'))

    def _load(self,frame):
        inputs=decode(_reference(self.kernel.log,frame['inputs']))
        if type(inputs) is not dict or inputs.get('schema')!=1 or inputs.get('identity')!=self.identity:raise AdmissionError('interpreter identity changed; no automatic migration')
        source=_reference(self.kernel.log,frame['definition']).decode('utf8')
        nodes=parse(source)
        if len(nodes)!=1:raise AdmissionError('scope definition must have one node')
        return nodes[0],inputs

    def _children(self,frame):
        return sorted((f for f in self.kernel.frames() if f['parent']==frame['id']),key=lambda f:f['parent_epoch'])

    def _environment(self,frame,inputs,node):
        env={k:_value(v) for k,v in inputs['bindings'].items()}
        # Only resumed predecessors enter lexical scope, never an early result.
        for child in self._children(frame):
            if child['parent_epoch']>frame['pc']:continue
            statement=node.body[child['parent_epoch']-1];value=_returned(self.kernel,child)
            if child['contract']==('RepeatResult','record'):
                env.update({k:_value(v) for k,v in value['bindings'].items()})
                env[_output(statement)]=Value('RepeatResult',dict(disposition=value['disposition'],iterations=value['iterations']))
            elif child['contract']==('BindingResult','record'):env[_output(statement)]=_value(value['value'])
            else:env[_output(statement)]=Value(child['contract'][0],value)
        return env

    def _visible_results(self,frame,contract):
        # A rejected proposal must not erase a read the model already saw. Derive
        # witnesses from resumed predecessor subtrees on this lexical ancestry;
        # never from an unsettled/unjoined sibling or another run. No read cache
        # or second history is persisted. Freshness is still checked at dispatch.
        frames={f['id']:f for f in self.kernel.frames()};children={}
        for value in frames.values():children.setdefault(value['parent'],[]).append(value)
        outcomes=[]
        def collect(value):
            if value['state']!='Closed':raise AdmissionError('visible predecessor is not closed')
            if value['contract']==contract:
                outcomes.append((value,_returned(self.kernel,value)))
            for child in children.get(value['id'],()):collect(child)
        cursor=frame
        while True:
            for prior in children.get(cursor['id'],()):
                if prior['parent_epoch']<=cursor['pc']:collect(prior)
            if cursor['parent'] is None:break
            cursor=frames[cursor['parent']]
        completed={entry['event']['frame']:index for index,entry in enumerate(self.kernel.log.events)
            if entry['event']['kind'] in ('returned','finished')}
        return tuple(sorted(outcomes,key=lambda item:completed[item[0]['id']]))

    def _visible_tool_outcomes(self,frame):
        return self._visible_results(frame,('ToolOutcome','record'))

    def _planning_model_for_tool(self,frame,operation_id):
        # Follow the actual ACT's lexical PLAN binding, not the last model
        # output in the log. Two equal tool proposals can have different origins.
        matches=[f for f,value in self._visible_tool_outcomes(frame) if value.get('operation_id')==operation_id]
        if not matches:return None
        if len(matches)!=1:raise AdmissionError('tool operation has ambiguous workflow ownership')
        tool=matches[0]
        parent=self.kernel.frame(tool['parent']);node,inputs=self._load(parent)
        index=tool['parent_epoch']-1
        if not 0<=index<len(node.body) or node.body[index].opcode!='ACT':
            raise AdmissionError('tool result does not belong to an admitted ACT')
        before={**parent,'pc':index}
        env=self._environment(before,inputs,node)
        plan=env[dict(node.body[index].attributes)['plan']]
        if plan.type!='ToolPlan' or plan.data.get('valid') is not True or plan.data['data']!=_reference(self.kernel.log,tool['inputs']):
            raise AdmissionError('tool result does not bind its lexical PLAN')
        identifier=plan.data.get('model_frame')
        if identifier is None:return None
        model=self.kernel.frame(identifier)
        if model['contract']!=('ModelOutput','record') or model['state']!='Closed' or _returned(self.kernel,model).get('model_frame')!=identifier:
            raise AdmissionError('tool PLAN has no settled original model output')
        return identifier

    def _observations(self,frame):
        return tuple(FileObservation(*value['observation']) for _,value in self._visible_tool_outcomes(frame)
            if value['observation'] is not None)

    def _pure(self,value,identifier,provenance=()):
        data=encode(dict(schema=1,value=value.wire,provenance=tuple((a.sha256,a.size_bytes) for a in provenance)))
        return CallSpec(identifier,'attempt-'+identifier[5:],'result','FLOW',self.kernel.log.put_artifact(encode(('bw.binding.v1',self.identity))),
            self.kernel.log.put_artifact(data),ResultContract('BindingResult','record'))

    def _verification(self,outcome,*,policy='unit-tests-and-finish',frame=None):
        result=self._verification_result(outcome,policy=policy,frame=frame)
        return dict(result,task_verdict=ladder_module.task_verdict(outcome,result),
                    outcome_operation_id=outcome.get('operation_id'))

    def _verification_result(self,outcome,*,policy='unit-tests-and-finish',frame=None):
        if policy in ('command-evidence-and-finish','file-readback-and-finish','page-capture-and-finish','page-inspection-and-finish','interactive-page-inspection-and-finish'):
            if self._file_policy is None or frame is None:raise AdmissionError('host file verification policy and visible scope required')
            if outcome.get('requested_finish') is not True:
                return dict(status='fail',policy=policy,reason='explicit finish request required')
            return self._file_policy.verify(self.registry,self.kernel.log,self._visible_tool_outcomes(frame))
        if policy!='unit-tests-and-finish':raise AdmissionError('unsupported verifier contract')
        # This explicitly named policy checks the actual registered unit-test
        # receipt and current bytes. It is not universal semantic acceptance or
        # protection against hostile test-output forgery by candidate code.
        if frame is None:raise AdmissionError('visible unit-test verification scope required')
        latest=None
        # A settled tool elsewhere in the log is not an observation available
        # to this continuation. Reuse lexical, resumed predecessor visibility.
        for candidate,value in self._visible_tool_outcomes(frame):
            if value['tool']=='run_tests':latest=(candidate,value)
        reason='finish request and successful current unit-test receipt required';passed=False
        if outcome.get('requested_finish') is True and latest:
            frame,value=latest
            if value['disposition']=='exited' and value['exit_code']==0:
                stderr=_reference(self.kernel.log,value['stderr'])
                count=re.search(rb'\nRan ([1-9][0-9]*) tests? in ',stderr)
                plan=decode(_reference(self.kernel.log,frame['inputs']))
                bound=(type(plan) is tuple and len(plan)==8
                    and plan[:4]==('bw.tool-plan.v2',self.registry.identity,self.registry.world,'run_tests')
                    and value.get('plan_sha256')==frame['inputs'][0]
                    and frame['dispatch'] is not None
                    and value.get('operation_id')==frame['dispatch'][0]
                    and frame['operation']==self.registry.operation_kind('run_tests')
                    and _reference(self.kernel.log,frame['definition'])==self.registry.definition_bytes('run_tests'))
                with self.registry.executor._lock:
                    self.registry._world_check();current=self.registry._inventory()
                passed=bound and count is not None and plan[6]==current
                reason='current unit-test receipt matched' if passed else 'empty test suite or workspace changed since tests'
        return dict(status='pass' if passed else 'fail',policy='unit-tests-and-finish',reason=reason)

    def _thinking_call(self,frame,identifier,profile_name,profile,source,content):
        mode=profile.pop('thinking_ladder')
        models={}
        for candidate,value in self._visible_results(frame,('ModelOutput','record')):
            owner=value.get('model_frame')
            if owner in models:continue
            actual=self.kernel.frame(owner)
            if (actual['state']!='Closed' or actual['contract']!=('ModelOutput','record')
                    or _reference(self.kernel.log,actual['definition'])!=self.adapter.definition):
                raise AdmissionError('planning origin is not a completed registered model FLOW')
            plan=self.adapter.plan(FrozenModelCall(_reference(self.kernel.log,actual['inputs'])))
            context=plan.get('planning')
            if context is None or context['profile']!=profile_name or context['mode']!=mode:continue
            returned=_returned(self.kernel,actual)
            if (value['plan_sha256']!=actual['inputs'][0] or returned['native_receipt']!=value['native_receipt']
                    or returned.get('model_frame')!=owner or returned.get('text')!=value.get('text')
                    or value['source_snapshot']!=plan['source']['tip']):
                raise AdmissionError('planning result changed its original model source')
            head=BranchHead.parse(value['native_receipt']['branch'])
            if head.root!=plan['source']['root']:
                raise AdmissionError('planning model result changed canonical root')
            models[owner]=dict(frame=actual,plan=plan,context=context,value=value,head=head)
        previous=next((m for m in reversed(tuple(models.values())) if m['head']==source),None)
        origin=identifier if previous is None else previous['context']['origin_model_frame']
        failures=[]
        if previous is not None:
            first=models.get(origin)
            if (first is None or first['context']['origin_model_frame']!=origin
                    or first['context']['rung']!=0 or first['context']['handled_failures']
                    or first['plan']['source']['root']!=source.root):
                raise AdmissionError('original thinking model is not visible in this root/profile')
            seen=set()
            outcomes={v['operation_id']:(f,v) for f,v in self._visible_tool_outcomes(frame)}
            for witness,value in self._visible_results(frame,('BindingResult','record')):
                wire=value.get('value')
                if type(wire) is not tuple or len(wire)!=2 or wire[0]!='Verification':continue
                verdict=wire[1];owner=verdict.get('planning_model_frame');model=models.get(owner)
                if verdict.get('task_verdict')!='verified_failure' or model is None or model['context']['origin_model_frame']!=origin:continue
                if _reference(self.kernel.log,witness['definition'])!=encode(('bw.binding.v1',self.identity)):
                    raise AdmissionError('thinking failure is not a registered host verification')
                operation=verdict.get('outcome_operation_id');observed=outcomes.get(operation)
                if (observed is None or ladder_module.task_verdict(observed[1],verdict)!='verified_failure'
                        or self._planning_model_for_tool(frame,operation)!=owner):
                    raise AdmissionError('thinking failure does not bind its original ACT/PLAN')
                tool_plan=decode(_reference(self.kernel.log,observed[0]['inputs']))
                proposed_tool,proposed_args=self.registry.parse(model['value']['text'])
                if (tool_plan[:4]!=('bw.tool-plan.v2',self.registry.identity,self.registry.world,'finish')
                        or proposed_tool!='finish' or proposed_args!=tool_plan[4]):
                    raise AdmissionError('failed finish differs from its original model proposal')
                if operation not in seen:
                    seen.add(operation);failures.append((operation,witness,model))
        handled=() if previous is None else previous['context']['handled_failures']
        failure_ids=tuple(row[0] for row in failures)
        if handled!=failure_ids[:len(handled)]:
            raise AdmissionError('thinking plan handled failures are not visible predecessors')
        rung=0 if previous is None else previous['context']['rung']
        retry=len(failure_ids)>len(handled)
        if retry:
            if len(failure_ids)!=len(handled)+1 or failures[-1][2]['frame']['id']!=previous['frame']['id']:
                raise AdmissionError('retry requires one newly failed current planning attempt')
            rung=ladder_module.next_attempt(mode,rung,'verified_failure')
            if rung is None:raise ThinkingLadderExhausted('all configured thinking rungs failed host verification')
        context=ladder_module.planning_context(dict(schema=1,profile=profile_name,mode=mode,rung=rung,
            origin_model_frame=origin,handled_failures=failure_ids))
        profile={**profile,'grammar_state':ladder_module.ladder(mode)[rung].grammar_state,'planning':context}
        if not retry:
            plan=self.adapter.freeze(source,mode=content[0],content=content[1],**profile)
            return model_call(self.kernel,self.adapter,child_id=identifier,attempt_id='attempt-'+identifier[5:],slot='result',plan=plan)
        # Reuse the failed call's exact input and boundary. Its prefix may not
        # yet contain the last tool/image feedback; do not discard that input.
        failed=previous['plan'];original=models[origin]['plan']['config']['content']
        def text(value):
            return value if type(value) is str else '\n'.join(v['text'] for v in value if v['type']=='text')
        goal=text(original)
        if len(goal.encode('utf8'))>32768:goal='Complete the original task retained in this branch and the preserved input.'
        observations=text(content[1])
        if len(observations.encode('utf8'))>32768:
            observations='[Tail of already-visible observations]\n'+observations.encode('utf8')[-32000:].decode('utf8',errors='replace')
        guidance=ladder_module.recovery_guidance(goal,observations)
        prior=failed['config']['content']
        if type(prior) is str:new_content=prior+'\n\n'+guidance
        else:
            new_content=model_content(prior)
            index=next(i for i in reversed(range(len(new_content))) if new_content[i]['type']=='text')
            new_content[index]['text']+='\n\n'+guidance
        with self.registry.executor._lock:
            self.registry._world_check()
            world=self.kernel.log.put_artifact(encode(('bw.planning-world.v1',self.registry.world,self.registry._inventory())))
        provenance=(Artifact(*failures[-1][1]['result']),Artifact(*previous['frame']['result']),
                    Artifact(*models[origin]['frame']['inputs']),world)
        return retry_module.retry_model_call(self.kernel,self.adapter,child_id=identifier,
            attempt_id='attempt-'+identifier[5:],slot='result',source=source,snapshot=failed['source']['tip'],
            mode=failed['config']['mode'],content=new_content,profile=profile,provenance=provenance)

    def _admit(self,frame,node,env):
        statement=node.body[frame['pc']];op=statement.opcode;a=dict(statement.attributes)
        identifier='call-'+sha256(encode((self.identity,frame['id'],frame['epoch'],frame['pc']))).hexdigest()[:48]
        provenance=()
        if op=='TEXT':value=Value('Text',statement.literal)
        elif op=='VALUE':value=env[a['ref']]
        elif op=='EXPAND':
            source=env[a['from']].data;profile=self.profiles[a['profile']]
            if 'thinking_ladder' in profile:
                return self._thinking_call(frame,identifier,a['profile'],profile,BranchHead.parse(source['head']),
                    (source['mode'],env[a['task']].data))
            plan=self.adapter.freeze(BranchHead.parse(source['head']),mode=source['mode'],content=env[a['task']].data,**profile)
            return model_call(self.kernel,self.adapter,child_id=identifier,attempt_id='attempt-'+identifier[5:],slot='result',plan=plan)
        elif op=='PLAN':
            if env[a['against']].data!=self.registry.world:raise AdmissionError('wrong world binding')
            proposed=env[a['from']];text=proposed.data['text'] if proposed.type=='ModelOutput' else proposed.data
            try:
                plan=self.registry.freeze(text,observations=self._observations(frame))
                value=Value('ToolPlan',dict(valid=True,data=plan.data,model_frame=proposed.data['model_frame'] if proposed.type=='ModelOutput' else None))
            except ToolRejected as exc:
                value=Value('ToolPlan',dict(valid=False,error=str(exc)[:1024],proposal_sha256=sha256(text.encode()).hexdigest()))
        elif op=='ACT':
            data=env[a['plan']].data
            if data['valid']:
                return tool_call(self.kernel,self.registry,child_id=identifier,attempt_id='attempt-'+identifier[5:],slot='result',plan=FrozenToolPlan(data['data']))
            outcome=ToolOutcome('rejected_before_admission',None,0.0,b'',data['error'].encode(),identifier,data['proposal_sha256'],'unadmitted')
            result,provenance=outcome.publish(self.kernel.log);value=Value('ToolOutcome',result)
        elif op=='TRANSFORM':
            source=env[a['input']]
            if a['contract']=='cow-source':
                value=Value('COWSource',dict(head=source.data['native_receipt']['branch'],mode='append_user'))
                value=_value(value.wire)
            else:
                data=source.data;observed=data['observation']
                observation=None if observed is None else dict(world=observed[0],path=observed[1],source_sha256=observed[2])
                feedback=dict(tool=data['tool'],operation_id=data['operation_id'],plan_sha256=data['plan_sha256'],disposition=data['disposition'],exit_code=data['exit_code'],observation=observation)
                if data['tool']=='run_shell':
                    # The accepted native argv already binds the exact program.
                    # Keep it beside its status so the model need not reconstruct
                    # quoting from an earlier proposal. This grants no new work.
                    feedback['command']=data['details']['argv'][-1]
                for field in ('stdout','stderr'):
                    raw=_reference(self.kernel.log,data[field]);shown=raw[:32768]
                    try:display=shown.decode('utf-8');lossy=False
                    except UnicodeDecodeError:display=shown.decode('utf-8',errors='replace');lossy=True
                    # A bounded text view is not the original output. Preserve
                    # the existing raw artifact and expose its exact identity;
                    # even a truncated valid stream can end inside a code point.
                    feedback[field]=display
                    feedback[field+'_truncated']=len(raw)>len(shown)
                    feedback[field+'_artifact']=dict(sha256=data[field][0],bytes=data[field][1])
                    feedback[field+'_display']=dict(encoding='utf-8',errors='replace',lossy=lossy,source_bytes=len(shown))
                if data['image'] is not None:
                    feedback['image']=dict(sha256=data['image'][0],bytes=data['image'][1],media_type='image/png')
                    feedback['capture']=data['details']
                text=json.dumps(feedback,ensure_ascii=True,sort_keys=True)
                if 'profile' in a:
                    if data['image'] is not None:
                        source_name=self.profiles[a['profile']]['source']
                        return image_feedback_call(self.kernel,self.adapter,identifier=identifier,
                            source=BranchHead.parse(env[source_name].data['head']),image=Artifact(*data['image']),text=text)
                    value=Value('ModelInput',text)
                else:value=Value('Text',text)
        elif op=='VERIFY':
            outcome=env[a['input']].data
            result=self._verification(outcome,policy=a['contract'],frame=frame)
            origin=self._planning_model_for_tool(frame,outcome.get('operation_id'))
            if origin is not None:result['planning_model_frame']=origin
            value=Value('Verification',result)
        elif op=='REPEAT':
            return CallSpec(identifier,'attempt-'+identifier[5:],'result','FLOW',self.kernel.log.put_artifact(render((statement,)).encode()),
                self.kernel.log.put_artifact(encode(dict(schema=1,identity=self.identity,bindings={k:v.wire for k,v in env.items()}))),ResultContract('RepeatResult','record'))
        else:raise AdmissionError('unsupported execution operation: '+op)
        return self._pure(value,identifier,provenance)

    def _scope(self,identifier):
        frame=self.kernel.frame(identifier);node,inputs=self._load(frame)
        if frame['state']=='Closed':return Step('complete',identifier,_returned(self.kernel,frame))
        if frame['state']=='Waiting':return self._wait(frame)
        if frame['state']!='Ready':raise AdmissionError('scope has unresolved settlement')
        env=self._environment(frame,inputs,node)
        if frame['pc']==len(node.body):
            verified=any(v.type=='Verification' and v.data.get('status')=='pass' for v in env.values())
            # Verification is meaningful only at the byte revision it checked.
            if verified:
                finishes=[v.data for v in env.values() if v.type=='ToolOutcome' and v.data.get('requested_finish') is True]
                verified=bool(finishes) and any(self._verification(finishes[-1],policy=v.data['policy'],frame=frame)['status']=='pass'
                    for v in env.values() if v.type=='Verification' and v.data.get('status')=='pass')
            value=dict(schema=1,bindings={k:v.wire for k,v in env.items()},verified=verified)
            self.kernel.finish(identifier,value);return Step('complete',identifier,value)
        try:call=self._admit(frame,node,env)
        except ThinkingLadderExhausted as exc:
            return Step('thinking_ladder_exhausted',identifier,dict(reason=str(exc)))
        self.kernel.spawn(identifier,expected_epoch=frame['epoch'],calls=(call,),next_pc=frame['pc']+1)
        return Step('admitted',call.child_id)

    def _repeat(self,identifier):
        frame=self.kernel.frame(identifier);node,inputs=self._load(frame);attrs=dict(node.attributes)
        if frame['state']=='Closed':return Step('complete',identifier,_returned(self.kernel,frame))
        if frame['state']=='Waiting':return self._wait(frame)
        if frame['state']!='Ready':raise AdmissionError('repeat has unresolved settlement')
        prior=None
        if frame['pc']:
            child=self._children(frame)[-1];prior=_returned(self.kernel,child)
            inputs=dict(inputs,bindings=prior['bindings'])
        tested=inputs['bindings'].get(attrs['until'])
        passed=bool(prior and tested and tested[0]=='Verification' and tested[1]['status']=='pass' and prior['verified'])
        if passed or frame['pc']>=int(attrs['max']):
            result=dict(schema=1,bindings=inputs['bindings'],iterations=frame['pc'],disposition='verified' if passed else 'exhausted')
            self.kernel.finish(identifier,result);return Step('complete',identifier,result)
        from .language import Statement
        definition=render((Statement('FLOW','iteration',body=node.body),)).encode()
        child_id='call-'+sha256(encode((self.identity,identifier,frame['epoch']))).hexdigest()[:48]
        call=CallSpec(child_id,'attempt-'+child_id[5:],'result','FLOW',self.kernel.log.put_artifact(definition),
            self.kernel.log.put_artifact(encode(inputs)),ResultContract('ProgramResult','record'))
        self.kernel.spawn(identifier,expected_epoch=frame['epoch'],calls=(call,),next_pc=frame['pc']+1)
        return Step('admitted',child_id)

    def _wait(self,frame):
        children=[c for c in self._children(frame) if c['parent_epoch']==frame['epoch']]
        if len(children)!=1:raise AdmissionError('sequential interpreter requires exactly one admitted child')
        child=children[0]
        if child['state']=='Closed':
            self.kernel.resume(frame['id'],frame['epoch']);return Step('resumed',frame['id'])
        contract=child['contract'][0]
        if contract=='ProgramResult':return self._scope(child['id'])
        if contract=='RepeatResult':return self._repeat(child['id'])
        if contract=='ModelOutput':
            if _reference(self.kernel.log,child['definition'])==retry_module.retry_definition(self.adapter):
                report=retry_module.step_retry_model(self.kernel,self.adapter,child['id'])
            else:report=step_model(self.kernel,self.adapter,child['id'])
            return Step('model_'+report.status,child['id'],report.value)
        if contract=='ToolOutcome':
            value=dispatch_tool(self.kernel,self.registry,child['id']);return Step('tool_returned',child['id'],value)
        if contract=='BindingResult':
            if self.adapter is not None and _reference(self.kernel.log,child['definition'])==feedback_definition(self.adapter):
                value=step_image_feedback(self.kernel,self.adapter,child['id'])
                return Step('image_uploaded',child['id'],value)
            if _reference(self.kernel.log,child['definition'])!=encode(('bw.binding.v1',self.identity)):raise AdmissionError('pure definition changed')
            value=decode(_reference(self.kernel.log,child['inputs']));_value(value['value'])
            self.kernel.finish(child['id'],dict(value=value['value']),provenance=tuple(Artifact(*a) for a in value['provenance']))
            return Step('binding_returned',child['id'])
        raise AdmissionError('unsupported admitted result contract')

    def step(self):
        root=self.kernel.frame('program');node,inputs=self._load(root)
        self._check_program(render((node,)),{k:_value(v) for k,v in inputs['bindings'].items()})
        return self._scope('program')

    def run(self,*,max_steps=1024):
        if type(max_steps) is not int or not 0<max_steps<=1000000:raise AdmissionError('finite positive step budget required')
        for _ in range(max_steps):
            report=self.step()
            if report.frame=='program' and report.status=='complete':return report
            if report.status in ('model_budget_exhausted','thinking_ladder_exhausted'):return report
        return Step('step_budget_exhausted','program')

"""One production frame/return controller on the canonical RuntimeLog.

This owns durable state transitions, not model tokens, world grants or an
alternative agent loop. Dispatch adapters and the general CLI are next.
"""
from copy import deepcopy
from dataclasses import dataclass
from decimal import Decimal
import hashlib
import re
from .records import Artifact, CorruptLog, decode, encode


class TransitionError(ValueError): pass


def _name(value):
    if type(value) is not str or not re.fullmatch(r'[A-Za-z][A-Za-z0-9_.:-]{0,127}',value):
        raise TransitionError('invalid host-owned identity')
    return value


def _integer(value):
    if type(value) is not int or value<0: raise TransitionError('nonnegative exact integer required')
    return value


def _ref(value):
    if type(value) is not tuple or len(value)!=2: raise TransitionError('invalid artifact binding')
    return Artifact(*value)


def _wire(ref):
    if not isinstance(ref,Artifact): raise TransitionError('typed artifact required')
    return (ref.sha256,ref.size_bytes)


@dataclass(frozen=True)
class ResultContract:
    name: str
    shape: str
    def __post_init__(self):
        _name(self.name)
        if self.shape not in ('bool','int','float','decimal','text','bytes','record','list','tuple','none'):
            raise TransitionError('unsupported result shape')
    @property
    def wire(self): return (self.name,self.shape)
    @property
    def digest(self):return hashlib.sha256(encode(('bw.result-contract.v1',*self.wire))).hexdigest()
    def check(self,value):
        typ={'bool':bool,'int':int,'float':float,'decimal':Decimal,'text':str,'bytes':bytes,
             'record':dict,'list':list,'tuple':tuple,'none':type(None)}[self.shape]
        if type(value) is not typ: raise TransitionError('result does not match the frozen contract')
        encode(value)


@dataclass(frozen=True)
class CallSpec:
    child_id: str
    attempt_id: str
    slot: str
    operation: str
    definition: Artifact
    inputs: Artifact
    result_contract: ResultContract
    def __post_init__(self):
        for value in (self.child_id,self.attempt_id,self.slot,self.operation):_name(value)
        _wire(self.definition);_wire(self.inputs)
        if not isinstance(self.result_contract,ResultContract):raise TransitionError('result contract required')
    @property
    def wire(self):
        return (self.child_id,self.attempt_id,self.slot,self.operation,
                _wire(self.definition),_wire(self.inputs),self.result_contract.wire)


_FIELDS={
 'root':{'frame','attempt','definition','inputs','contract'},
 'spawn':{'parent','source_epoch','calls','next_pc'},
 'dispatched':{'frame','operation_id','request'},
 'returned':{'frame','operation_id','result','provenance','settled'},
 'settled':{'frame','operation_id','receipt'},
 'resumed':{'parent','epoch'},
 'finished':{'frame','result','provenance'},
}


class FrameKernel:
    def __init__(self,log):
        self.log=log;self._seen=0;self._state=dict(frames={},groups={},operations={})
        try:
            for row in log.events:
                expected=self._references(row['event'])
                if set(row['artifacts'])!={_wire(a) for a in expected}:
                    raise TransitionError('event artifact roots do not match its bindings')
                self._apply(self._state,row['event']);self._seen+=1
        except (ValueError,TypeError,KeyError,IndexError) as exc:
            raise CorruptLog('invalid production frame transition') from exc

    def _check(self):
        if self.log.event_count!=self._seen:raise TransitionError('stale controller projection; reopen/replay')

    def _references(self,event):
        if (type(event) is not dict or type(event.get('schema')) is not int or event['schema']!=1
                or event.get('kind') not in _FIELDS
                or set(event)!=_FIELDS[event['kind']]|{'schema','kind'}):
            raise TransitionError('invalid frame event schema')
        kind=event['kind'];refs=[]
        if kind=='root':refs=[event['definition'],event['inputs']]
        elif kind=='spawn':
            if type(event['calls']) is not tuple or not 1<=len(event['calls'])<=256:
                raise TransitionError('bounded nonempty call tuple required')
            for call in event['calls']:
                if type(call) is not tuple or len(call)!=7:raise TransitionError('invalid call binding')
                refs.extend(call[4:6])
        elif kind=='dispatched':refs=[event['request']]
        elif kind in ('returned','finished'):
            if type(event['provenance']) is not tuple:raise TransitionError('provenance tuple required')
            refs=[event['result'],*event['provenance']]
        elif kind=='settled':refs=[event['receipt']]
        result=tuple(_ref(r) for r in refs)
        for ref in result:self.log.read_artifact(ref)
        return tuple(dict.fromkeys(result))

    @staticmethod
    def _frame(identifier,attempt,parent,parent_epoch,slot,operation,definition,inputs,contract):
        _name(identifier);_name(attempt);_name(operation)
        contract=ResultContract(*contract)
        return dict(id=identifier,attempt=attempt,parent=parent,parent_epoch=parent_epoch,slot=slot,
            operation=operation,definition=definition,inputs=inputs,contract=contract.wire,
            contract_id=contract.digest,state='Ready',pc=0,epoch=0,dispatch=None,result=None,
            result_settled=False,settlement_receipt=None)

    def _apply(self,state,event):
        kind=event['kind'];frames=state['frames'];groups=state['groups'];operations=state['operations']
        if kind=='root':
            candidate=self._frame(event['frame'],event['attempt'],None,None,None,'FLOW',
                                  event['definition'],event['inputs'],event['contract'])
            if candidate['id'] in frames:
                prior=frames[candidate['id']]
                if any(prior[k]!=candidate[k] for k in ('attempt','parent','operation','definition','inputs','contract')):
                    raise TransitionError('root identity reused for different work')
                return False
            if frames:raise TransitionError('one root per run; use child scopes')
            frames[candidate['id']]=candidate
        elif kind=='spawn':
            parent=frames[event['parent']];old=_integer(event['source_epoch']);epoch=old+1
            key=(event['parent'],epoch)
            if key in groups:
                if groups[key]['admission']!=event:raise TransitionError('changed wait admission')
                return False
            if parent['state']!='Ready' or parent['epoch']!=old:raise TransitionError('parent is not ready at this epoch')
            _integer(event['next_pc']);children=[];slots=set();ids=set()
            for call in event['calls']:
                child,attempt,slot,op,definition,inputs,contract=call;_name(slot)
                if slot in slots or child in ids or child in frames:raise TransitionError('duplicate slot/child')
                slots.add(slot);ids.add(child)
                children.append(self._frame(child,attempt,parent['id'],epoch,slot,op,definition,inputs,contract))
            for child in children:frames[child['id']]=child
            groups[key]=dict(admission=deepcopy(event),expected={c['slot']:c['id'] for c in children},filled={},resumed=False)
            parent.update(state='Waiting',epoch=epoch)
        elif kind=='dispatched':
            frame=frames[event['frame']];op=_name(event['operation_id']);binding=(op,event['request'])
            if frame['dispatch'] is not None:
                if frame['dispatch']!=binding:raise TransitionError('unresolved/dispatched operation cannot be replaced')
                return False
            if frame['state']!='Ready' or op in operations:raise TransitionError('dispatch identity/state conflict')
            operations[op]=frame['id'];frame.update(state='Waiting',dispatch=binding)
        elif kind=='returned':
            frame=frames[event['frame']]
            if frame['dispatch'] is None or event['operation_id']!=frame['dispatch'][0]:
                raise TransitionError('return has no matching dispatched operation')
            if type(event['settled']) is not bool:raise TransitionError('settlement is a host boolean')
            payload=decode(self.log.read_artifact(_ref(event['result'])))
            if (type(payload) is not tuple or len(payload)!=4 or payload[0]!='bw.result.v1'
                    or payload[1]!=frame['contract'] or payload[3]!=event['provenance']):
                raise TransitionError('result artifact has a different contract/provenance')
            ResultContract(*frame['contract']).check(payload[2])
            if frame['result'] is not None:
                if frame['result']!=event['result']:raise TransitionError('conflicting return')
                if frame['state']=='Settling' and event['settled']:
                    raise TransitionError('explicit resource settlement receipt required')
                return False
            if frame['state']!='Waiting':raise TransitionError('frame cannot return now')
            frame.update(result=event['result'],result_settled=event['settled'],
                         state='Closed' if event['settled'] else 'Settling')
            if event['settled']:self._deliver(state,frame)
        elif kind=='finished':
            frame=frames[event['frame']]
            if frame['operation']!='FLOW':raise TransitionError('only a FLOW may return without external dispatch')
            payload=decode(self.log.read_artifact(_ref(event['result'])))
            if (type(payload) is not tuple or len(payload)!=4 or payload[0]!='bw.result.v1'
                    or payload[1]!=frame['contract'] or payload[3]!=event['provenance']):
                raise TransitionError('FLOW result contract/provenance mismatch')
            ResultContract(*frame['contract']).check(payload[2])
            if frame['state']=='Closed':
                if frame['result']!=event['result']:raise TransitionError('conflicting FLOW return')
                return False
            if frame['state']!='Ready':raise TransitionError('FLOW has unresolved waits/effects')
            frame.update(state='Closed',result=event['result'],result_settled=True);self._deliver(state,frame)
        elif kind=='settled':
            frame=frames[event['frame']]
            if frame['dispatch'] is None or event['operation_id']!=frame['dispatch'][0]:
                raise TransitionError('settlement owner mismatch')
            if frame['settlement_receipt'] is not None:
                if frame['settlement_receipt']!=event['receipt']:raise TransitionError('changed settlement proof')
                return False
            if frame['state']!='Settling' or frame['result'] is None:raise TransitionError('no result awaiting settlement')
            frame.update(state='Closed',result_settled=True,settlement_receipt=event['receipt']);self._deliver(state,frame)
        elif kind=='resumed':
            parent=frames[event['parent']];epoch=_integer(event['epoch']);group=groups[(parent['id'],epoch)]
            if group['resumed']:return False
            if (parent['state']!='Waiting' or parent['epoch']!=epoch
                    or set(group['filled'])!=set(group['expected'])):raise TransitionError('wait is not completely settled')
            group['resumed']=True;parent.update(state='Ready',pc=group['admission']['next_pc'])
        return True

    @staticmethod
    def _deliver(state,frame):
        if frame['parent'] is None:return
        group=state['groups'][(frame['parent'],frame['parent_epoch'])]
        if group['expected'].get(frame['slot'])!=frame['id']:raise TransitionError('return slot owner mismatch')
        existing=group['filled'].get(frame['slot'])
        if existing is not None and existing!=frame['result']:raise TransitionError('conflicting slot delivery')
        group['filled'][frame['slot']]=frame['result']

    def _commit(self,kind,**fields):
        self._check();event=dict(schema=1,kind=kind,**fields)
        try:
            refs=self._references(event);candidate=deepcopy(self._state)
            changed=self._apply(candidate,event)
        except (KeyError,TypeError,IndexError) as exc:raise TransitionError('unknown/malformed frame binding') from exc
        if changed:
            self.log.append(event,artifacts=refs);self._state=candidate;self._seen+=1
        return changed

    def create_root(self,frame_id,attempt_id,definition,inputs,contract):
        self._commit('root',frame=frame_id,attempt=attempt_id,definition=_wire(definition),
                     inputs=_wire(inputs),contract=contract.wire)
        return self.frame(frame_id)

    def spawn(self,parent,*,expected_epoch,calls,next_pc):
        if type(calls) is not tuple or any(not isinstance(c,CallSpec) for c in calls):
            raise TransitionError('host call specifications required')
        self._commit('spawn',parent=parent,source_epoch=expected_epoch,calls=tuple(c.wire for c in calls),next_pc=next_pc)
        return expected_epoch+1

    def dispatch(self,frame,operation_id,request):
        return self._commit('dispatched',frame=frame,operation_id=operation_id,request=_wire(request))

    def record_result(self,frame,operation_id,value,*,provenance=(),settled=True):
        self._check();current=self.frame(frame);ResultContract(*current['contract']).check(value)
        refs=tuple(_wire(a) for a in provenance)
        result=self.log.put_artifact(encode(('bw.result.v1',current['contract'],value,refs)))
        self._commit('returned',frame=frame,operation_id=operation_id,result=_wire(result),provenance=refs,settled=settled)
        return result

    def finish(self,frame,value,*,provenance=()):
        self._check();current=self.frame(frame);ResultContract(*current['contract']).check(value)
        refs=tuple(_wire(a) for a in provenance)
        result=self.log.put_artifact(encode(('bw.result.v1',current['contract'],value,refs)))
        self._commit('finished',frame=frame,result=_wire(result),provenance=refs)
        return result

    def settle(self,frame,operation_id,receipt):
        return self._commit('settled',frame=frame,operation_id=operation_id,receipt=_wire(receipt))

    def resume(self,parent,epoch):return self._commit('resumed',parent=parent,epoch=epoch)

    def frame(self,identifier):
        self._check();return deepcopy(self._state['frames'][identifier])

    def frames(self):
        """Detached inventory for the owning interpreter, never worker authority."""
        self._check();return tuple(deepcopy(v) for v in self._state['frames'].values())

    def ready(self):
        self._check();return tuple(k for k,v in self._state['frames'].items() if v['state']=='Ready')

    def slot_value(self,parent,epoch,slot):
        self._check();ref=self._state['groups'][(parent,epoch)]['filled'][slot]
        return decode(self.log.read_artifact(_ref(ref)))[2]

"""Prepare the existing coding workflow; COW and RuntimeLog remain authoritative."""
import hashlib,json,os,re,stat,tempfile
from pathlib import Path
from .run_cli import _config,_pairs,execute,_source_notice
from .cow_client import CowClient,HTTPTransport,OperationJournal,OperationIndeterminate
PROGRAM="""FLOW coding
REPEAT attempts exhausted=stop max=32 until=verified
EXPAND decide from=current profile=control task=task -> proposed
PLAN freeze against=world from=proposed -> plan
ACT perform plan=plan -> outcome
TRANSFORM advance contract=cow-source input=proposed -> current
TRANSFORM feedback contract=tool-feedback input=outcome -> task
VERIFY check contract=command-evidence-and-finish input=outcome -> verified
END
END
"""
MAX_LAUNCH_BYTES=1024*1024
def _bytes(value):
    return json.dumps(value,sort_keys=True,separators=(',',':'),ensure_ascii=True,allow_nan=False).encode()
def build_launch(project,task,connection,*,branch,read_paths=(),edit_paths=(),create_paths=(),test_commands=(),from_branch=None,from_snapshot=None,shell_timeout=120):
    project=Path(project).resolve(strict=True)
    if not project.is_dir():raise ValueError('project must be a directory')
    keys={'endpoint_url','endpoint_pin','model_contract_id','execution_profile_id','eos_tokens'}
    if type(connection) is not dict or set(connection)!=keys:
        raise ValueError('connection needs only endpoint/profile identities and EOS IDs; credentials belong in BW_COW_API_KEY')
    HTTPTransport(connection['endpoint_url'])
    if type(task) is not str or not task.strip() or len(task.encode('utf8'))>262144:raise ValueError('bounded nonempty task text required')
    if type(branch) is not str or not 1<=len(branch)<=128:raise ValueError('bounded branch name required')
    if not test_commands or any(type(c) is not str or not c.strip() for c in test_commands):
        raise ValueError('at least one explicit verification command is required')
    if from_snapshot is not None and from_branch is None:raise ValueError('a snapshot requires its source branch')
    if from_branch is not None and (type(from_branch) is not str or not from_branch):raise ValueError('source branch required')
    if from_snapshot is not None and (type(from_snapshot) is not str or not re.fullmatch('[0-9a-f]{64}',from_snapshot)):raise ValueError('invalid source snapshot')
    cow=dict(connection,branch=branch,mode='ask',bootstrap='coding',grammar_registration='inline')
    fork=None
    if from_branch is not None:
        cow.pop('bootstrap');cow['mode']='append_user'
        fork=dict(source_branch=from_branch,snapshot=from_snapshot)
    config=dict(schema=1,source=str(project),run_id=branch,
        grant=dict(read_paths=sorted(set(read_paths)|set(edit_paths)|set(create_paths)),
                   edit_paths=list(edit_paths),create_paths=list(create_paths),allow_tests=False,allow_shell=True),
        bindings=dict(task=dict(type='Text',value=task)),cow=cow,
        shell=dict(timeout=shell_timeout),
        verification=dict(schema=1,commands=[dict(command=c,disposition='exited',exit_code=0) for c in test_commands]))
    config=_config(_bytes(config).decode())
    return dict(schema=1,program=PROGRAM,config=config,fork=fork)
def _validate(launch):
    if type(launch) is not dict or set(launch)!={'schema','program','config','fork'} or type(launch['schema']) is not int or launch['schema']!=1 or launch['program']!=PROGRAM:
        raise ValueError('unsupported coding launch')
    _config(_bytes(launch['config']).decode())
    fork=launch['fork']
    if fork is not None:
        if (type(fork) is not dict or set(fork)!={'source_branch','snapshot'}
                or type(fork['source_branch']) is not str or not fork['source_branch']
                or type(fork['snapshot']) is not str or not re.fullmatch('[0-9a-f]{64}',fork['snapshot'])
                or launch['config']['cow'].get('mode')!='append_user'
                or 'bootstrap' in launch['config']['cow']):
            raise ValueError('retained launch must pin an exact source snapshot')
    elif launch['config']['cow'].get('bootstrap')!='coding':
        raise ValueError('new coding launch requires its bootstrap')
def _state(state,*,create=False,source=None):
    state=Path(state).absolute()
    if state.is_symlink():raise ValueError('state must be a real owned directory')
    if source is not None and state.resolve().is_relative_to(Path(source).resolve()):
        raise ValueError('run state must be outside the source project')
    if create and not state.exists():state.mkdir(mode=0o700)
    info=state.lstat()
    if not stat.S_ISDIR(info.st_mode) or stat.S_IMODE(info.st_mode)!=0o700 or info.st_uid!=os.getuid():
        raise ValueError('state must be an owned directory with mode0700')
    return state
def save_launch(state,launch):
    import fcntl
    _validate(launch)
    state=_state(state,create=True,source=launch['config']['source'])
    raw=_bytes(dict(launch=launch,sha256=hashlib.sha256(_bytes(launch)).hexdigest()))+b'\n'
    if len(raw)>MAX_LAUNCH_BYTES:raise ValueError('coding launch is too large')
    path=state/'coding-launch.json'
    # Serialize trusted setup publishers; atomic rename leaves one file link
    # even if the process stops before staging cleanup. No workflow lives here.
    lockfd=os.open(state/'.coding-launch.lock',os.O_RDWR|os.O_CREAT|getattr(os,'O_NOFOLLOW',0),0o600)
    with os.fdopen(lockfd,'r+b') as lock:
        info=os.fstat(lock.fileno())
        if not stat.S_ISREG(info.st_mode) or info.st_nlink!=1 or info.st_uid!=os.getuid() or stat.S_IMODE(info.st_mode)!=0o600:
            raise ValueError('invalid coding setup lock')
        fcntl.flock(lock.fileno(),fcntl.LOCK_EX)
        if path.exists() or path.is_symlink():
            if read_launch(state)!=launch:raise ValueError('run setup changed; use a new run state')
            return
        fd,name=tempfile.mkstemp(prefix='.coding-launch-',dir=state);temporary=Path(name)
        try:
            with os.fdopen(fd,'wb') as stream:
                os.fchmod(stream.fileno(),0o600);stream.write(raw);stream.flush();os.fsync(stream.fileno())
            os.replace(temporary,path)
            directory=os.open(state,os.O_RDONLY|getattr(os,'O_DIRECTORY',0))
            try:os.fsync(directory)
            finally:os.close(directory)
        finally:
            if temporary.exists():temporary.unlink()
def read_launch(state):
    state=_state(state)
    fd=os.open(state/'coding-launch.json',os.O_RDONLY|getattr(os,'O_NOFOLLOW',0)|getattr(os,'O_NONBLOCK',0))
    with os.fdopen(fd,'rb') as stream:
        info=os.fstat(stream.fileno())
        if not stat.S_ISREG(info.st_mode) or info.st_nlink!=1 or info.st_uid!=os.getuid() or stat.S_IMODE(info.st_mode)!=0o600:
            raise ValueError('coding launch must be a private owned regular file')
        raw=stream.read(MAX_LAUNCH_BYTES+1)
    if len(raw)>MAX_LAUNCH_BYTES:raise ValueError('coding launch is too large')
    envelope=json.loads(raw)
    if type(envelope) is not dict or set(envelope)!={'launch','sha256'} or envelope['sha256']!=hashlib.sha256(_bytes(envelope['launch'])).hexdigest():
        raise ValueError('coding launch integrity check failed')
    _validate(envelope['launch'])
    return envelope['launch']
def _client(state,launch):
    cow=launch['config']['cow']
    return CowClient.http(cow['endpoint_url'],journal=OperationJournal(Path(state)/'cow-operations'),api_key=os.environ.get('BW_COW_API_KEY'),endpoint_pin=cow['endpoint_pin'],notice_handler=_source_notice)
def run_saved(state,*,max_steps=1024):
    if type(max_steps) is not int or max_steps<=0:raise ValueError('finite positive step budget required')
    launch=read_launch(state)
    if launch['fork'] is not None:
        fork=launch['fork'];operation='bw-code-fork-'+hashlib.sha256(_bytes(launch)).hexdigest()[:40]
        # The original pinned source and journal ID survive retries. An uncertain
        # fork remains uncertain; never select a newer head or invent a new ID.
        try:
            _client(state,launch).fork(fork['source_branch'],fork['snapshot'],launch['config']['cow']['branch'],operation)
        except OperationIndeterminate as exc:
            raise OperationIndeterminate('Original fork operation '+operation+' is unresolved; reconcile its original journal intent before continuing') from exc
    return execute('run',launch['program'],_bytes(launch['config']).decode(),state,max_steps=max_steps)
def start(args):
    if type(args.max_steps) is not int or args.max_steps<=0:raise ValueError('finite positive step budget required')
    from .__main__ import _source
    connection=json.loads(_source(args.connection),object_pairs_hook=_pairs)
    launch=build_launch(args.project,_source(args.task_file),connection,branch=args.branch,
        read_paths=args.read,edit_paths=args.edit,create_paths=args.create,
        test_commands=args.test_command,from_branch=args.from_branch,
        from_snapshot=args.from_snapshot,shell_timeout=args.shell_timeout)
    existing=Path(args.state)/'coding-launch.json'
    if launch['fork'] is not None and launch['fork']['snapshot'] is None:
        if existing.exists():
            prior=read_launch(args.state)
            if prior['fork'] is not None and prior['fork']['source_branch']==args.from_branch:
                launch['fork']['snapshot']=prior['fork']['snapshot']
        if launch['fork']['snapshot'] is None:
            # Read-only selection before publication. The snapshot,not a live
            # branch name,is saved before any mutating setup/inference request.
            launch['fork']['snapshot']=_client(args.state,launch).head(args.from_branch).tip
    save_launch(args.state,launch)
    return run_saved(args.state,max_steps=args.max_steps)

"""Pinned Linux commands and opt-in model shell in read-only namespaces.

The model can compose shell commands only with an explicit host grant/config.
Both forms use one worker and the same file projection, process retirement and
receipt boundary. Writes use separate granted file tools; this is not an admin
capability or persistent terminal session. Writable shells need separate scopes.
"""
from dataclasses import dataclass,field
import base64,hashlib,json,math,os,re,stat,subprocess,tempfile,time
from pathlib import Path
from .execution import ToolRejected,ToolResult,Executor,_operation_id,_MAX_CAPTURE_BYTES

def _stat_key(info):
    return (info.st_dev,info.st_ino,info.st_size,info.st_mtime_ns,info.st_ctime_ns,stat.S_IMODE(info.st_mode))

@dataclass(frozen=True)
class NamedCommand:
    name: str
    argv: tuple[str,...]
    timeout: float=10.0
    _binary_key: tuple=field(init=False,repr=False)
    binary_sha256: str=field(init=False)
    def __post_init__(self):
        if (type(self.name) is not str or re.fullmatch('[A-Za-z][A-Za-z0-9_-]{0,31}',self.name) is None
                or type(self.argv) is not tuple or not 1<=len(self.argv)<=64
                or any(type(v) is not str or '\0' in v for v in self.argv)
                or sum(len(v.encode('utf8')) for v in self.argv)>32768
                or type(self.timeout) not in (int,float) or not math.isfinite(self.timeout)
                or not 0<self.timeout<=120):
            raise ToolRejected('bounded immutable host command definition required')
        executable=Path(self.argv[0])
        if (not executable.is_absolute() or str(executable)!=self.argv[0]
                or executable.parent not in (Path('/usr/bin'),Path('/bin'))
                or not executable.is_file() or not os.access(executable,os.X_OK)):
            raise ToolRejected('command executable must be a host system binary')
        # Ubuntu 26 packages coreutils as /usr/bin aliases into /usr/lib/cargo.
        # Admit root-owned, non-writable packaged targets throughout /usr;
        # a /usr/bin spelling must not grant a link to user-owned code.
        target=executable.resolve(strict=True)
        if not target.is_relative_to('/usr'):
            raise ToolRejected('command target is outside the system runtime')
        for path in (target,*target.parents):
            info=path.stat()
            if info.st_uid!=0 or info.st_mode&0o022:
                raise ToolRejected('command target has writable or non-root ownership')
            if path==Path('/usr'):break
        with executable.open('rb') as stream:
            info=os.fstat(stream.fileno());digest=hashlib.file_digest(stream,'sha256').hexdigest()
            if _stat_key(os.fstat(stream.fileno()))!=_stat_key(info):raise ToolRejected('command executable changed')
        object.__setattr__(self,'timeout',float(self.timeout))
        object.__setattr__(self,'_binary_key',_stat_key(info))
        object.__setattr__(self,'binary_sha256',digest)
    def check(self):
        if _stat_key(Path(self.argv[0]).stat())!=self._binary_key:raise ToolRejected('registered command executable changed')
    @property
    def wire(self):return (self.name,self.argv,self.timeout,self.binary_sha256,self._binary_key)

def command_table(commands):
    if type(commands) is not tuple or len(commands)>32 or any(not isinstance(v,NamedCommand) for v in commands):
        raise ToolRejected('bounded immutable host command tuple required')
    if len({v.name for v in commands})!=len(commands):raise ToolRejected('duplicate host command name')
    return tuple(sorted(commands,key=lambda v:v.name))

@dataclass(frozen=True)
class CommandResult(ToolResult):
    details: dict
    assets: tuple = ()

def _release_bytes():
    path=Path('/etc/os-release').resolve(strict=True)
    with path.open('rb') as stream:
        before=os.fstat(stream.fileno())
        if not stat.S_ISREG(before.st_mode) or before.st_size>65536:raise ToolRejected('bounded host OS release unavailable')
        body=stream.read(65537)
        if len(body)!=before.st_size or _stat_key(os.fstat(stream.fileno()))!=_stat_key(before):
            raise ToolRejected('host OS release changed')
    return body

def execute_command(executor,operation_id,grant,name):
    operation_id=_operation_id(operation_id)
    if name not in grant.command_names:raise ToolRejected('command is not granted')
    command=next((v for v in executor._commands if v.name==name),None)
    if command is None:raise ToolRejected('unknown host command')
    return _execute_argv(executor,operation_id,grant,command,command.argv)

def _execute_argv(executor,operation_id,grant,command,command_argv):
    command.check()
    info=executor.workspace.lstat()
    if not stat.S_ISDIR(info.st_mode) or (info.st_dev,info.st_ino)!=executor._workspace_identity:
        raise ToolRejected('owned workspace is stale/replaced')
    # Snapshot only readable files. The child cannot read neighboring workspace
    # files, the caller's home, credentials, protected checks, or the live source.
    outputs=grant.output_paths
    from .command_outputs import initial_state,configure_namespace,publish,OUTPUT_LIMIT
    output_preimages=initial_state(executor,outputs) if outputs else ()
    inputs=[];bodies=[];total=0
    for path in grant.read_paths:
        if path in grant.create_paths:
            # A readable future output need not exist yet. Project absence,
            # not an empty/fabricated file; tests may legitimately fail before
            # the model creates it. Links/unsafe paths still fail closed.
            try:executor._workspace_file(path)
            except FileNotFoundError:continue
        if path in outputs:
            try:executor._workspace_file(path)
            except FileNotFoundError:continue
        body=executor._read_private_bytes(path);total+=len(body)
        if total>64*1024**2:raise ToolRejected('command readable inputs exceed bound')
        mode=stat.S_IMODE(executor._workspace_file(path).stat(follow_symlinks=False).st_mode)&0o777
        inputs.append(dict(path=path,bytes=len(body),sha256=hashlib.sha256(body).hexdigest(),mode=format(mode,'04o')))
        bodies.append((path,body,mode))
    release=_release_bytes()
    started=time.monotonic()
    with tempfile.TemporaryDirectory(prefix='command-',dir=executor.run_dir) as temporary:
        stage=Path(temporary);projection=stage/'input';projection.mkdir(mode=0o700)
        for path,body,mode in bodies:
            destination=projection/path;destination.parent.mkdir(mode=0o700,parents=True,exist_ok=True)
            # Preserve execution/read semantics. The namespace mount below
            # remains read-only even when the copied basic mode includes write.
            destination.write_bytes(body);destination.chmod(mode)
        release_file=stage/'os-release';release_file.write_bytes(release);release_file.chmod(0o400)
        package=Path(__file__).resolve().parent
        argv=['/usr/bin/prlimit','--core=0','--fsize=16777216','--as=2147483648',
            '--cpu='+str(math.ceil(command.timeout)+2),'--','/usr/bin/bwrap',
            '--die-with-parent','--new-session','--unshare-all','--unshare-user',
            '--disable-userns','--cap-drop','ALL','--clearenv']
        for path in ['/usr','/lib','/lib64']:argv+=['--ro-bind',path,path]
        argv+=['--proc','/proc','--dev','/dev','--size','67108864','--tmpfs','/tmp','--chmod','1777','/tmp',
            '--dir','/etc','--ro-bind',str(release_file),'/etc/os-release',
            '--ro-bind',str(package),'/app/branchwrite',
            '--ro-bind',str(projection),str(executor.workspace)]
        output_capacity=configure_namespace(argv,projection,executor.workspace,outputs) if outputs else {}
        argv+=['--chdir',str(executor.workspace),
            '--setenv','PATH','/usr/bin:/bin','--setenv','LANG','C.UTF-8',
            '--','/usr/bin/python3','-I','-B','/app/branchwrite/terminal_worker.py']
        request_row=dict(argv=command_argv,timeout=command.timeout)
        if outputs:request_row.update(schema=2,outputs=list(outputs))
        request=json.dumps(request_row,separators=(',',':')).encode()
        if len(request)>1024**2:raise ToolRejected('command request exceeds framing bound')
        if not hasattr(os,'memfd_create'):raise ToolRejected('terminal isolation requires Linux memfd')
        descriptor=os.memfd_create('bw-command-request',os.MFD_CLOEXEC)
        process=None
        try:
            with os.fdopen(descriptor,'w+b') as stream:
                stream.write(request);stream.seek(0)
                process=subprocess.Popen(argv,stdin=stream,stdout=subprocess.PIPE,stderr=subprocess.PIPE,
                    close_fds=True,start_new_session=True,env={'PATH':'/usr/bin:/bin','LANG':'C.UTF-8'})
            out,err,timed_out,limited,_=Executor._capture(process,time.monotonic()+command.timeout+3,((OUTPUT_LIMIT+2*_MAX_CAPTURE_BYTES)*4//3+1024**2) if outputs else 3*1024**2)
        finally:
            if process is not None and process.poll() is None:
                import signal
                Executor._signal_group(process,signal.SIGKILL);process.wait(timeout=3)
        if timed_out or limited or process.returncode!=0:
            raise ValueError('terminal worker did not settle: '+err.decode('utf8','replace')[-512:])
        row=json.loads(out)
        fields={'schema','argv','cwd','disposition','exit_code','stdout','stderr','isolation'}
        if outputs:fields|={'outputs','output_error'}
        if (type(row) is not dict or set(row)!=fields or row['schema']!=(2 if outputs else 1)
                or row['argv']!=list(command_argv) or row['cwd']!=str(executor.workspace)
                or row['disposition'] not in ('exited','timeout','output_limit','spawn_error')
                or (row['exit_code'] is not None and type(row['exit_code']) is not int)):
            raise ValueError('invalid terminal worker receipt')
        witness=row['isolation']
        if (type(witness) is not dict or witness.get('kind')!='bubblewrap-terminal-v1'
                or any(type(witness.get(name)) is not str
                    or witness[name]==os.readlink('/proc/self/ns/'+suffix)
                    for name,suffix in [('pid_ns','pid'),('net_ns','net'),('mount_ns','mnt')])):
            raise ValueError('terminal namespace isolation is not proven')
        from .browser_isolation import await_namespace_retirement
        members=await_namespace_retirement(witness['pid_ns'])
        if members:raise ValueError('terminal namespace retirement is not proven')
        witness.update(worker_exited=True,launcher_pid=process.pid,namespace_members_after=members)
        stdout=base64.b64decode(row['stdout'],validate=True);stderr=base64.b64decode(row['stderr'],validate=True)
        if max(len(stdout),len(stderr))>_MAX_CAPTURE_BYTES:raise ValueError('terminal output exceeds capture bound')
        details=dict(command=command.name,argv=list(command_argv),binary_sha256=command.binary_sha256,
            cwd=row['cwd'],inputs=inputs,os_release_sha256=hashlib.sha256(release).hexdigest(),
            execution_host=dict(hostname=os.uname().nodename,uid=os.getuid(),euid=os.geteuid(),gid=os.getgid()),
            isolation=witness,scope='host-fixed argv;read-only captured readable files;no network or host home')
        assets=()
        if outputs:
            if row['output_error'] is not None:
                if type(row['output_error']) is not str or len(row['output_error'])>512:raise ValueError('invalid output rejection')
                details.update(outputs=[],output_error=row['output_error'],output_capacity=output_capacity)
                row['disposition']='output_rejected'
            else:
                receipts,assets=publish(executor,outputs,output_preimages,row['outputs'],operation_id)
                details.update(outputs=receipts,output_capacity=output_capacity)
        # Only publish after actual namespace retirement. Upstream publication
        # uncertainty keeps the original intent unresolved; it is not resend.
        result=executor._result(operation_id,row['disposition'],row['exit_code'],started,stdout,stderr)
        return CommandResult(result.operation_id,result.disposition,result.exit_code,result.elapsed_seconds,
            result.stdout,result.stderr,details,assets)

MAX_SHELL_BYTES=16384

@dataclass(frozen=True)
class ShellConfig:
    """Host selects pinned Bash, timeout and optional executor hostname."""
    timeout: float=10.0
    expected_hostname: str|None=None
    _command: NamedCommand=field(init=False,repr=False)
    def __post_init__(self):
        if self.expected_hostname is not None and (type(self.expected_hostname) is not str
                or re.fullmatch(r'[A-Za-z0-9][A-Za-z0-9_.-]{0,252}',self.expected_hostname) is None):
            raise ToolRejected('bounded executor hostname required')
        self.check_host()
        command=NamedCommand('shell',('/usr/bin/bash','--noprofile','--norc'),self.timeout)
        object.__setattr__(self,'timeout',command.timeout)
        object.__setattr__(self,'_command',command)
    @property
    def wire(self):return ('bw.readonly-shell.v1',self._command.wire,MAX_SHELL_BYTES,self.expected_hostname)
    def check_host(self):
        actual=os.uname().nodename
        if self.expected_hostname is not None and actual!=self.expected_hostname:
            raise ToolRejected('executor host mismatch: expected '+self.expected_hostname+', observed '+actual)
    def validate(self,text):
        self.check_host()
        if type(text) is not str or not text or '\0' in text or len(text.encode('utf8'))>MAX_SHELL_BYTES:
            raise ToolRejected('bounded nonempty shell command required')
        self._command.check()
        return self._command.argv+('-c',text)

def execute_shell(executor,operation_id,grant,text):
    operation_id=_operation_id(operation_id)
    if not grant.allow_shell or executor._shell is None:raise ToolRejected('shell is not granted/configured')
    config=executor._shell;argv=config.validate(text)
    result=_execute_argv(executor,operation_id,grant,config._command,argv)
    result.details['scope']=('model-written Bash; protected inputs; bounded declared outputs; no network or host home' if grant.output_paths else 'model-written Bash; read-only captured readable files; no network or host home')
    return result
